class Solution { public: vector<vector<int>> rotateGrid(vector<vector<int>>& grid,int k){int rows=grid.size(),cols=grid[0].size();for(int layer=0;layer<min(rows,cols)/2;++layer){int top=layer,bottom=rows-1-layer,left=layer,right=cols-1-layer;vector<pair<int,int>> positions;for(int col=left;col<=right;++col)positions.push_back({top,col});for(int row=top+1;row<=bottom;++row)positions.push_back({row,right});for(int col=right-1;col>=left;--col)positions.push_back({bottom,col});for(int row=bottom-1;row>top;--row)positions.push_back({row,left});vector<int> values;for(auto [row,col]:positions)values.push_back(grid[row][col]);int shift=k%values.size();for(int i=0;i<(int)positions.size();++i){auto [row,col]=positions[i];grid[row][col]=values[(i+shift)%values.size()];}}return grid;} };
